import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose2d_cute_forward(torch::Tensor x,
                                            torch::Tensor w,
